package com.example.starter.blind;

import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.Import;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 测试数据隔离基类：每个用例前清空全部业务表，避免顺序依赖。
 */
@Import(TestClockConfig.class)
public abstract class AbstractBlindIntegrationTest {

    @Autowired
    protected JdbcTemplate jdbc;

    @Autowired
    protected MutableTestClock clock;

    @BeforeEach
    void cleanTables() {
        // 无外键约束，顺序无依赖；全部清空保证场景独立。
        jdbc.update("DELETE FROM idempotent_request");
        jdbc.update("DELETE FROM unblind_request");
        jdbc.update("DELETE FROM allocation");
        jdbc.update("DELETE FROM seat");
        jdbc.update("DELETE FROM experiment");
        clock.setTime(1_700_000_000_000L);
    }
}
package com.example.starter.blind;

import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 测试时钟配置：以可控时钟替换系统墙钟；
 * MutableTestClock 实现 Clock，Clock 类型注入点按 @Primary 命中该 Bean。
 * 同时注册 H2 释放 Bean，上下文结束时关闭命名内存库。
 */
@TestConfiguration
public class TestClockConfig {

    @Bean
    @Primary
    public MutableTestClock mutableTestClock() {
        return new MutableTestClock();
    }

    @Bean
    public H2ShutdownBean h2ShutdownBean(JdbcTemplate jdbc) {
        return new H2ShutdownBean(jdbc);
    }
}
package com.example.starter.blind;

/**
 * 测试用可控时钟；可手动设置当前时间，避免时间相关断言依赖真实睡眠。
 */
public class MutableTestClock implements Clock {

    private volatile long current = 1_700_000_000_000L;

    @Override
    public long nowMillis() {
        return current;
    }

    public void setTime(long millis) {
        this.current = millis;
    }

    public void advance(long millis) {
        this.current += millis;
    }
}
package com.example.starter.blind;

import org.springframework.beans.factory.DisposableBean;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 测试上下文销毁时释放命名 H2 内存库：DB_CLOSE_DELAY=-1 使库不随连接关闭，
 * 因此在 JVM 退出前显式 SHUTDOWN，避免库在上下文结束后仍驻留。
 */
public class H2ShutdownBean implements DisposableBean {

    private final JdbcTemplate jdbc;

    public H2ShutdownBean(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public void destroy() {
        jdbc.execute("SHUTDOWN");
    }
}

