 * 主流程：建实验、顺序分配、盲码视图、满额、退组不释放席位、关闭拒绝新增。
 */
@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
class BlindExperimentApiTest extends AbstractBlindIntegrationTest {

    @Autowired
    private TestRestTemplate rest;

    private final ObjectMapper mapper = new ObjectMapper();

    private HttpHeaders headers(String actor, String role, String requestId) {
        HttpHeaders h = new HttpHeaders();
        h.set("X-Actor-Id", actor);
        h.set("X-Role", role);
        if (requestId != null) {
            h.set("X-Request-Id", requestId);
        }
        h.setContentType(MediaType.APPLICATION_JSON);
        return h;
    }

    private ResponseEntity<String> exchange(String path, HttpMethod method,
                                            HttpHeaders headers, String body) {
        return rest.exchange(path, method, new HttpEntity<>(body, headers), String.class);
    }

    private JsonNode json(ResponseEntity<String> response) throws Exception {
        return mapper.readTree(response.getBody());
    }

    @Test
    void createExperiment_fixedBlocksAndSeats_twoATwoBPerBlock() {
        ResponseEntity<String> resp = exchange("/api/experiments/EXP-1", HttpMethod.POST,
                headers("c1", "COORDINATOR", "req-create-1"), "{\"blockCount\":2}");
        assertEquals(201, resp.getStatusCode().value());
        JsonNode body = resp.getBody() == null ? null : parse(resp.getBody());
        assertNotNull(body);
        assertEquals("EXP-1", body.path("experimentId").asText());
        assertEquals(2, body.path("blockCount").asInt());
        assertEquals(4, body.path("seatsPerBlock").asInt());
        assertEquals(8, body.path("totalSeats").asInt());
        assertEquals("OPEN", body.path("status").asText());
        assertEquals(1_700_000_000_000L, body.path("createdAt").asLong());
        // 普通视图不得含盲底字段
        assertFalse(body.has("treatment"));
        assertFalse(body.has("seatNo"));

        // 库内席位映射：每区组按顺序两个 A、两个 B
        List<String> treatments = jdbc.queryForList(
                "SELECT treatment FROM seat WHERE experiment_id = 'EXP-1' "
                        + "ORDER BY block_no, seat_no", String.class);
        assertEquals(List.of("A", "A", "B", "B", "A", "A", "B", "B"), treatments);
        assertEquals(8, jdbc.queryForObject(
                "SELECT COUNT(*) FROM seat WHERE experiment_id = 'EXP-1'", Integer.class));
    }
package com.example.starter.blind.web;

import com.example.starter.blind.Actor;
import com.example.starter.blind.ActorContext;
import com.example.starter.blind.Role;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.http.MediaType;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.Map;

/**
 * 业务接口鉴权过滤器：本题信任本地测试头 X-Actor-Id / X-Role。
 * 仅拦截 /api/** ；头缺失或角色非法直接 401，不进入业务与幂等逻辑。
 */
@Component
public class ActorHeaderFilter extends OncePerRequestFilter {

    public static final String HEADER_ACTOR = "X-Actor-Id";
    public static final String HEADER_ROLE = "X-Role";

    private final ActorContext actorContext;
    private final ObjectMapper objectMapper;

    public ActorHeaderFilter(ActorContext actorContext, ObjectMapper objectMapper) {
        this.actorContext = actorContext;
        this.objectMapper = objectMapper;
    }

    @Override
    protected boolean shouldNotFilter(HttpServletRequest request) {
        return !request.getRequestURI().startsWith("/api/");
    }

    @Override
    protected void doFilterInternal(HttpServletRequest request,
                                    HttpServletResponse response,
                                    FilterChain filterChain) throws ServletException, IOException {
        try {
            String actorId = request.getHeader(HEADER_ACTOR);
            String roleHeader = request.getHeader(HEADER_ROLE);
            if (actorId == null || actorId.isBlank() || roleHeader == null || roleHeader.isBlank()) {
                writeError(response, HttpServletResponse.SC_UNAUTHORIZED, "缺少 X-Actor-Id 或 X-Role 请求头");
                return;
            }
            if (actorId.trim().length() > 64) {
                writeError(response, HttpServletResponse.SC_BAD_REQUEST, "X-Actor-Id 长度不能超过 64 个字符");
                return;
            }
            final Role role;
            try {
                role = Role.valueOf(roleHeader.trim());
            } catch (IllegalArgumentException e) {
                writeError(response, HttpServletResponse.SC_UNAUTHORIZED, "X-Role 仅允许 COORDINATOR 或 REVIEWER");
                return;
            }
            actorContext.set(new Actor(actorId.trim(), role));
            filterChain.doFilter(request, response);
        } finally {
            actorContext.clear();
        }
    }

    private void writeError(HttpServletResponse response, int status, String message) throws IOException {
        response.setStatus(status);
        response.setContentType(MediaType.APPLICATION_JSON_VALUE);
        response.setCharacterEncoding("UTF-8");
        objectMapper.writeValue(response.getWriter(),
                Map.of("error", "UNAUTHORIZED", "message", message));
    }
}
package com.example.starter.blind.web;

import com.example.starter.blind.ApiException;
import com.example.starter.blind.dto.ErrorBody;
import com.example.starter.blind.service.IdempotencyService;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.FieldError;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingRequestHeaderException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;

/**
 * 全局异常处理；错误信息不包含处理代码或席位序号。
 */
@RestControllerAdvice
public class GlobalExceptionHandler {

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<ErrorBody> handleApi(ApiException ex) {
        return ResponseEntity.status(ex.getStatus())
                .body(new ErrorBody(ex.getStatus().getReasonPhrase(), ex.getMessage()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<ErrorBody> handleValidation(MethodArgumentNotValidException ex) {
        FieldError fieldError = ex.getBindingResult().getFieldError();
        String message = fieldError != null ? fieldError.getDefaultMessage() : "请求参数不合法";
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody(HttpStatus.BAD_REQUEST.getReasonPhrase(), message));
    }

    @ExceptionHandler(HttpMessageNotReadableException.class)
    public ResponseEntity<ErrorBody> handleUnreadable(HttpMessageNotReadableException ex) {
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody(HttpStatus.BAD_REQUEST.getReasonPhrase(), "请求体格式不正确"));
    }

    @ExceptionHandler(MissingRequestHeaderException.class)
    public ResponseEntity<ErrorBody> handleMissingHeader(MissingRequestHeaderException ex) {
        String message = IdempotencyService.HEADER_REQUEST_ID.equals(ex.getHeaderName())
                ? "写操作必须携带全局唯一 X-Request-Id 请求头"
                : "缺少必需请求头: " + ex.getHeaderName();
        return ResponseEntity.status(HttpStatus.BAD_REQUEST)
                .body(new ErrorBody(HttpStatus.BAD_REQUEST.getReasonPhrase(), message));
    }
}

