        assertEquals("ACTIVE", records.get(1).path("status").asText());
        assertEquals("SMP-PRE-1", records.get(1).path("supersedesSampleNo").asText());

        // 锁定冻结更正后的摘要
        ResponseEntity<String> lockResp = lock("EXP-S4", "P1", "c1", "s4-lock", 3);
